package com.spendwise.spendwise.controller;
import java.time.YearMonth; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import com.spendwise.spendwise.dto.MonthlySummaryResponse; import com.spendwise.spendwise.service.MonthlySummaryService;
@RestController @RequestMapping("/api/transactions") public class MonthlySummaryController {private final MonthlySummaryService service;public MonthlySummaryController(MonthlySummaryService service){this.service=service;}@GetMapping("/summary") public MonthlySummaryResponse getMonthlySummary(@RequestParam @DateTimeFormat(pattern="yyyy-MM") YearMonth month,Authentication authentication){return service.getMonthlySummary(month,authentication.getName());}}
